import{z as o,x as s,o as e,c as m,q as n,j as l,D as a,d as r,s as i,S as t,b as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"重排序器的工程","description":"","frontmatter":{"title":"重排序器的工程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-reranker-engineering.md","filePath":"llm/rag-reranker-engineering.md","lastUpdated":1791413859000}'),p={name:"llm/rag-reranker-engineering.md"};function d(D,E,C,h,F,T){const A=s("Mermaid");return e(),m("div",null,[E[2]||(E[2]=n('<h1 id="重排序器的工程" tabindex="-1">重排序器的工程 <a class="header-anchor" href="#重排序器的工程" aria-label="Permalink to &quot;重排序器的工程&quot;">​</a></h1><div class="epigraph"><p>重排是检索链上最贵的可选项，也是最容易被默认开着、从不重审的一段；预算要倒着推，精度要挨着量。</p><footer>—— Nogueira 与 Cho 的 BERT 重排路线；Santhanam 等 ColBERTv2 的蒸馏口径；据重排工程实践整理</footer></div><p><a href="/llm/rag-hybrid-weight-learning">上一课</a>把融合权重做成可学习的对象；融合保召回，前排精度由重排买。重排的原理与两段式分工在主干<a href="/llm/rerank">重排序</a>课：双塔召回、交叉编码器逐对打分、点式对式列表式之分。本课写把它做进生产的四件事：窗口 \\(m\\) 怎么定、模型怎么选与蒸馏、阈值拒答怎么设、什么时候才轮到 LLM 列表排序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>重排的延迟近似是 \\(m\\) 次编码器前向（可批），\\(m\\) 从 50 加到 200，延迟约线性涨四倍，而精度增益先升后饱和——增益的上界是上一课融合列表里的有效真值深度，列表里没有的真值，重排变不出来。生产病症有两种：重排默认全开，简单查询也在为个位数点的增益付几百毫秒；或者从不重审 \\(m\\) 与模型，召回换代后难负例分布已变，旧重排器把新的真值块打低，前排精度悄悄回退。</p><p><span class="marginnote">把 \\(m\\) 想成「进复试的人数」：召回先海选几百份简历，重排是面试官逐个细看。算笔账——单条前向约 2 毫秒、\\(m=200\\) 时，一个查询光重排就要约 0.4 秒；而前排只有 5 个位置，第 51 名之后基本进不了答案。所以 \\(m\\) 够用就好，不是越大越好。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算倒推。定检索段 p99 预算，减去嵌入与 ANN 的实测开销，剩余除以批量后的单条前向时间，得到 \\(m\\) 上限；再在验证集上画精度–\\(m\\) 曲线，取饱和点之前的值。模型选型把深度当旋钮：层数少的检查点换延迟，层多的换精度，<a href="/llm/bge-reranker-v2">BGE Reranker v2</a> 的 layerwise 口径即此；更大提升来自蒸馏——用大交叉编码器或 LLM 对候选逐对打分当教师，训小模型学相对序，ColBERTv2 用同一思路去噪监督。难负例直接取上一课融合列表的高排名非答案块，比随机负例有用。</p><p>阈值拒答是重排独有的产品能力：点式分数校准后，低于阈值不送生成器、直接回「证据不足」，比硬凑 \\(n\\) 块安全；分数分布不稳时用相对规则——至少留一块、分差小于 \\(\\delta\\) 多留。缓存同查询的重排结果，批内按长度分桶减少 padding 浪费。</p><p><span class="marginnote">术语速记：双塔是「问题和文档各算各的向量再比距离」，快到可以提前算好存索引里，但精度粗；交叉编码器是「把问题和候选拼在一起逐字对照打分」，准但每个查询都要现算。一个管海选、一个管终面，蒸馏就是把终面官的判断力教给便宜的替身。</span></p>',10)),(e(),l(t,null,{default:a(()=>[i(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E6%A3%80%E7%B4%A2%E6%AE%B5%20p99%20%E9%A2%84%E7%AE%97%22%5D%20--%3E%20MINUS%5B%22%E5%87%8F%E5%8E%BB%E5%B5%8C%E5%85%A5%E4%B8%8E%20ANN%20%E5%AE%9E%E6%B5%8B%E5%BC%80%E9%94%80%22%5D%0A%20%20MINUS%20--%3E%20MUP%5B%22%E5%BE%97%20m%20%E4%B8%8A%E9%99%90%22%5D%0A%20%20MUP%20--%3E%20CURVE%5B%22%E9%AA%8C%E8%AF%81%E9%9B%86%E7%94%BB%E7%B2%BE%E5%BA%A6%E2%80%93m%20%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20CURVE%20--%3E%20PICK%5B%22%E5%8F%96%E9%A5%B1%E5%92%8C%E7%82%B9%E5%89%8D%E7%9A%84%20m%22%5D%0A%20%20PICK%20--%3E%20THR%5B%22%E5%88%86%E6%95%B0%E6%A0%A1%E5%87%86%E8%AE%BE%E6%8B%92%E7%AD%94%E9%98%88%E5%80%BC%22%5D%0A%20%20THR%20--%3E%20SERVE%5B%22%E6%89%B9%E5%A4%84%E7%90%86%20%2B%20%E7%BC%93%E5%AD%98%E4%B8%8A%E7%BA%BF%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[r("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"蒸馏为什么有效：教师逐对分数比人工标签细，学生学的是候选间的相对结构而非绝对分，绝对分随域漂移，相对序稳定得多。\\(m\\) 为什么饱和：超过融合列表的有效真值深度后，重排只是在排列噪声，精度曲线走平而费用继续线性。LLM 列表排序为什么不上热路径：一次调用的延迟与费用接近又一次生成，且提示里的位置偏差让窗口中部候选吃亏；它的正确用途是离线标注与当蒸馏教师，线上热路径默认小模型点式重排。",-1)),(e(),l(t,null,{default:a(()=>[i(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E8%9E%8D%E5%90%88%E5%80%99%E9%80%89%E5%88%97%E8%A1%A8%EF%BC%8C%E7%BA%A6%20m%20%E6%9D%A1%22%5D%20--%3E%20TEA%5B%22%E6%95%99%E5%B8%88%EF%BC%9A%E5%A4%A7%E4%BA%A4%E5%8F%89%E7%BC%96%E7%A0%81%E5%99%A8%E6%88%96%20LLM%22%5D%0A%20%20TEA%20--%3E%20PAIR%5B%22%E9%80%90%E5%AF%B9%E6%89%93%E5%88%86%EF%BC%8C%E4%BA%A7%E5%87%BA%E7%9B%B8%E5%AF%B9%E5%BA%8F%22%5D%0A%20%20PAIR%20--%3E%20STU%5B%22%E5%AD%A6%E7%94%9F%EF%BC%9A%E5%B0%8F%E6%A8%A1%E5%9E%8B%E5%AD%A6%E7%9B%B8%E5%AF%B9%E5%BA%8F%E8%80%8C%E9%9D%9E%E7%BB%9D%E5%AF%B9%E5%88%86%22%5D%0A%20%20STU%20--%3E%20HOT%5B%22%E9%83%A8%E7%BD%B2%E5%88%B0%E7%BA%BF%E4%B8%8A%E7%83%AD%E8%B7%AF%E5%BE%84%EF%BC%8C%E9%80%90%E5%80%99%E9%80%89%E6%89%93%E5%88%86%22%5D%0A%20%20HARD%5B%22%E9%9A%BE%E8%B4%9F%E4%BE%8B%EF%BC%9A%E8%9E%8D%E5%90%88%E5%88%97%E8%A1%A8%E9%AB%98%E6%8E%92%E5%90%8D%E9%9D%9E%E7%AD%94%E6%A1%88%E5%9D%97%22%5D%20--%3E%20STU%0A%20%20HOT%20--%3E%20DRIFT%7B%22%E5%8F%AC%E5%9B%9E%E6%8D%A2%E4%BB%A3%E6%88%96%E5%9F%9F%E6%BC%82%E7%A7%BB%EF%BC%9F%22%7D%0A%20%20DRIFT%20--%3E%7C%E6%98%AF%7C%20RETEA%5B%22%E9%87%8D%E6%96%B0%E8%92%B8%E9%A6%8F%E6%88%96%E9%87%8D%E6%A0%A1%E5%87%86%E9%98%88%E5%80%BC%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">这张图回答「蒸馏怎么把贵模型的眼光搬进热路径」。关键在「学相对序」：教师不告诉学生「这篇该打 7.3 分」（绝对分换个域就失效），只告诉它「这篇比那篇更相关」，这种比较关系稳定得多，小模型也学得会。</span></p><p><span class="marginnote">重排窗口里的重叠切块不去重，前三名会是同一节的三份拷贝——近重复在重排后放大，因为交叉编码器对同一文本给出几乎相同的分。去重要在进重排窗口之前做。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>重排不创造召回里没有的真值，召回侧（切分、嵌入、索引、融合）仍决定上限。重排器与双塔、切分版本绑定：召回换代要重挖难负例、重蒸馏或重校准阈值。拒答率是必须报告的量：阈值收紧，拒答升、忠实度看似升——只是把难题推出了管道，端到端价值要用带拒答分支的评测算。多跳场景逐跳重排会叠延迟，通常只在把结果送生成器前的那一次重排。预算与降级路径怎么在服务里编排，是后面延迟与成本课的缺口。</p><p><span class="marginnote">常见误区：看到「拒答率上升」就以为系统变坏了。实际上收紧阈值后，一部分难题从「硬凑证据乱答」变成了「坦白说证据不足」——乱答变坦白，忠实度当然升。真正要算的是端到端三笔账：答对多少、正确拒答多少、答错多少。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(m\\) 由延迟预算倒推、精度曲线收尾；饱和之后全是白付的延迟。</li><li>模型选型把深度当旋钮，大提升走蒸馏：教师逐对打分，学生学相对序。</li><li>难负例取融合列表高排名非答案块；召回换代必须重训或重校准。</li><li>点式分数校准换阈值拒答；拒答率是要报告的量，不是丑话。</li><li>LLM 列表排序留在离线与教师位，热路径用小交叉编码器。</li><li>出处：Nogueira 与 Cho；Santhanam 等 ColBERTv2；BGE Reranker v2 模型卡。</li></ul>',7))])}const c=o(p,[["render",d]]);export{_ as __pageData,c as default};
